import { CatalogItem, CategoryId, Era } from '../types/catalog';

function eraFromYear(year: number): Era {
  if (year < 1980) return '1970s';
  if (year < 1990) return '1980s';
  if (year < 2000) return '1990s';
  if (year < 2010) return '2000s';
  if (year < 2020) return '2010s';
  return '2020s';
}

export type CategoryTuple = [
  id: string,
  category: CategoryId,
  title: string,
  year: number,
  creator: string,
  origin: string,
  rating: number,
  durationOrFormat: string,
  tags: string[],
  moods: string[],
  summary: string,
  whyNotable: string,
  hints?: { wikiPage?: string; imageQuery?: string; franchise?: string; language?: string }
];

export function mapTuples(tuples: CategoryTuple[]): CatalogItem[] {
  return tuples.map(
    ([id, category, title, year, creator, origin, rating, durationOrFormat, tags, moods, summary, whyNotable, hints]) => ({
      id,
      title,
      category,
      year,
      era: eraFromYear(year),
      creator,
      tags,
      moods,
      rating,
      isNew: year >= 2024,
      origin,
      durationOrFormat,
      summary,
      whyNotable,
      franchise: hints?.franchise,
      language: hints?.language,
      wikiPage: hints?.wikiPage,
      imageQuery: hints?.imageQuery,
    })
  );
}

